// streebogC holds the twelve round constants the key schedule mixes in
// between rounds, one 64-byte constant per round.
// streebogRoundConstants is the twelve round constants, held behind a
// function so they are not package state a caller could reassign.
func streebogRoundConstants() [12][64]byte {
	return [12][64]byte{
		streebogByteArray(streebogC1), streebogByteArray(streebogC2), streebogByteArray(streebogC3), streebogByteArray(streebogC4),
		streebogByteArray(streebogC5), streebogByteArray(streebogC6), streebogByteArray(streebogC7), streebogByteArray(streebogC8),
		streebogByteArray(streebogC9), streebogByteArray(streebogC10), streebogByteArray(streebogC11), streebogByteArray(streebogC12),
	}
}

// streebogByteArray converts one of the raw 64-byte round-constant
// strings into an array: Go only converts a string to an array by way of
// a slice, not directly from an untyped string constant.
func streebogByteArray(s string) [64]byte {
	return [64]byte([]byte(s))
}

